use super::*;
/// 🧾️ Original nested diagnostics, target allocations, paid effects and independent receipt refusal remain borrowed.
#[test]
fn original_member_failure_projection_borrows_complete_typed_source(){
 let messages=vec![MutationMessage::fatal("mutation.invariant","original child payload").at(vec!["page".to_string(),"drawing".to_string()])];let pointer=messages[0].message.as_ptr();let target=messages[0].target[1].as_ptr();let p=RetainedCloneProgress{copied_items:1,copied_bytes:17,retained_capacity_bytes:23,released_bytes:5};let source=OriginalMemberPublicationFailure{source:E::Rejected{policy:MergePolicy::Vigilant,messages},effects:p,receipt_refusal:Some(ValueError::literal(ValueRefusalKind::OwnershipLimit,"original receipt refused"))};assert_eq!(source.domain_retained_progress(),p);assert_eq!(source.projection_key(&[],0).unwrap(),"source");match source.projection_view(&[0,0]).unwrap(){V::IntrinsicText(kind)=>assert_eq!(kind,"rejected"),_=>panic!("original variant missing")};match source.projection_view(&[0,1,1,0,2]).unwrap(){V::IntrinsicText(message)=>assert_eq!(message.as_ptr(),pointer),_=>panic!("original diagnostic missing")};match source.projection_view(&[0,1,1,0,3,1]).unwrap(){V::IntrinsicText(value)=>assert_eq!(value.as_ptr(),target),_=>panic!("original target missing")};match source.projection_view(&[1,2]).unwrap(){V::IntrinsicNumber(Number::UInt(value))=>assert_eq!(value,23),_=>panic!("original effects missing")};assert!(source.projection_view(&[2]).is_ok());
 let mut original=Some(source);let mut close=semio_framework_value::retained_clone::RetainedCloneClose::default();let g=semio_framework_value::RetainedCloneGrant{maximum_items:1,maximum_copy_bytes:1<<20,maximum_capacity_bytes:1<<20,maximum_release_bytes:1<<20,maximum_depth:128};for _ in 0..10000{if let Some(_)=close.begin_granted(&mut original,g).unwrap(){continue}if close.is_empty(){assert!(original.is_none());return}close.step_granted(g).unwrap();}panic!("original member refusal did not retire")
}
